add_action( 'init', 'perfectpixel_move_cross_sells' );
add_filter( 'woocommerce_cross_sells_total', 'perfectpixel_cross_sells_total' );
add_filter( 'woocommerce_cross_sells_columns', 'perfectpixel_cross_sells_columns' );

function perfectpixel_move_cross_sells() {
	remove_action( 'woocommerce_cart_collaterals', 'woocommerce_cross_sell_display' );
	add_action( 'woocommerce_after_cart', 'woocommerce_cross_sell_display' );
}

function perfectpixel_cross_sells_total() {
	return max( 1, (int) '{{cross_sells_total}}' );
}

function perfectpixel_cross_sells_columns() {
	return max( 1, (int) '{{cross_sells_columns}}' );
}
